def orientations(shape):
    pts=shape
    outs=[]
    for k in range(4):
        # rotate
        pts=[(c,-r) for r,c in pts]
        norm=(min(r for r,c in pts),min(c for r,c in pts))
        q=[(r-norm[0],c-norm[1]) for r,c in pts]
        for reflected in (False,True):
            p2=[(r,-c) for r,c in q] if reflected else q
            n2=(min(r for r,c in p2),min(c for r,c in p2))
            outs.append(tuple(sorted((r-n2[0],c-n2[1]) for r,c in p2)))
    return set(outs)
