    base=(min(r for r,c in P),min(c for r,c in P))
    P=tuple(sorted((r-base[0],c-base[1]) for r,c in P))
    ors=orientations(list(P))
    cover=set()
    for o in ors:
        h=max(r for r,c in o); w=max(c for r,c in o)
        for r in range(Hh-h):
            for c in range(Ww-w):
                if all(0<=r+dr<Hh and 0<=c+dc<Ww and A[r+dr,c+dc] in (bg,marker) for dr,dc in o):
                    for dr,dc in o: cover.add((r+dr,c+dc))
    mism=sum(1 for r in range(Hh) for c in range(Ww) if A[r,c]==bg and ((r,c) in cover)!=(Y[r,c]!=bg))
    return mism, len(ors)
