def hyp_iter(A,Y,bg,marker,return_grid=False):
    Hh,Ww=A.shape
    P=[(r,c) for r in range(Hh) for c in range(Ww) if A[r,c]==marker]
    base=(min(r for r,c in P),min(c for r,c in P))
    P=[(r-base[0],c-base[1]) for r,c in P]
    h=max(r for r,c in P); w=max(c for r,c in P)
    cur=A.copy()
    while True:
        fillset=set()
        for r in range(Hh-h):
            for c in range(Ww-w):
                if all(cur[r+dr,c+dc]==bg for dr,dc in P):
                    for dr,dc in P: fillset.add((r+dr,c+dc))
        if not fillset: break
        for r,c in fillset: cur[r,c]=marker
    mis=sum(1 for r in range(Hh) for c in range(Ww) if A[r,c]==bg and (cur[r,c]!=bg)!=(Y[r,c]!=bg))
    return (mis,cur) if return_grid else mis
